   const first = store.claimScratch({ resource: 'path:payments/**', ownerWorker: 'w1', ownerTask: 't1', intent: 'edit', envRef: envA, fence: 3, leaseDeadline: 'later' }, { actor: 'w1', key: 'claim-a' });
